# Let me now understand what parameters the ZSTD_CCtx_setParameter accepts
# These are the key compression parameters I need

# Let me look at what specific enums/defines I need
# ZSTD_cParameter enum values - from public API:
# ZSTD_c_compressionLevel = 100
# ZSTD_c_checksumFlag = 201
# ZSTD_c_nbWorkers = 400
# etc.

# Let me create a test program to verify the enum values work
cat > /tmp/test_zstd_api.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>

typedef void ZSTD_CCtx;
typedef void ZSTD_DCtx;

// ZSTD parameter enums (from public API)
typedef enum {
    ZSTD_c_compressionLevel = 100,
    ZSTD_c_windowLog = 101,
    ZSTD_c_hashLog = 102,
    ZSTD_c_chainLog = 103,
    ZSTD_c_searchLog = 104,
    ZSTD_c_minMatch = 105,
    ZSTD_c_targetLength = 106,
    ZSTD_c_strategy = 107,
    ZSTD_c_enableLongDistanceMatching = 160,
    ZSTD_c_ldmHashLog = 161,
    ZSTD_c_ldmMinMatch = 162,
    ZSTD_c_ldmBucketSizeLog = 163,
    ZSTD_c_ldmHashRateLog = 164,
    ZSTD_c_contentSizeFlag = 200,
    ZSTD_c_checksumFlag = 201,
    ZSTD_c_dictIDFlag = 202,
    ZSTD_c_nbWorkers = 400,
    ZSTD_c_jobSize = 401,
    ZSTD_c_overlapLog = 402,
} ZSTD_cParameter;

int main() {
    void *lib = dlopen("/usr/lib/x86_64-linux-gnu/libzstd.so.1", RTLD_LAZY);
    if (!lib) { printf("Failed\n"); return 1; }

    ZSTD_CCtx* (*createCCtx)() = dlsym(lib, "ZSTD_createCCtx");
    size_t (*setParam)(ZSTD_CCtx*, ZSTD_cParameter, int) = dlsym(lib, "ZSTD_CCtx_setParameter");
    int (*isError)(size_t) = dlsym(lib, "ZSTD_isError");
    const char* (*getError)(size_t) = dlsym(lib, "ZSTD_getErrorName");
    size_t (*freeCCtx)(ZSTD_CCtx*) = dlsym(lib, "ZSTD_freeCCtx");

    ZSTD_CCtx *ctx = createCCtx();
    size_t r = setParam(ctx, ZSTD_c_compressionLevel, 3);
    printf("setParam compressionLevel: %zu, error=%d (%s)\n", r, isError(r), getError(r));
    r = setParam(ctx, ZSTD_c_checksumFlag, 1);
    printf("setParam checksumFlag: %zu, error=%d (%s)\n", r, isError(r), getError(r));
    r = setParam(ctx, ZSTD_c_nbWorkers, 4);
    printf("setParam nbWorkers: %zu, error=%d (%s)\n", r, isError(r), getError(r));

    freeCCtx(ctx);
    dlclose(lib);
    return 0;
}
EOF
gcc -o /tmp/test_zstd_api /tmp/test_zstd_api.c -ldl && /tmp/test_zstd_api

