# nbWorkers is not supported in this library version (1.4.8)
# The library supports some but not all parameters - that's OK, we just need to handle errors gracefully

# Let me test compression/decompression using the streaming API
cat > /tmp/test_compress.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

typedef void ZSTD_CCtx;
typedef void ZSTD_DCtx;

typedef struct {
    const void* src;
    size_t size;
    size_t pos;
} ZSTD_inBuffer;

typedef struct {
    void* dst;
    size_t size;
    size_t pos;
} ZSTD_outBuffer;

typedef enum {
    ZSTD_e_continue = 0,
    ZSTD_e_flush = 1,
    ZSTD_e_end = 2
} ZSTD_EndDirective;

int main() {
    void *lib = dlopen("/usr/lib/x86_64-linux-gnu/libzstd.so.1", RTLD_LAZY);
    if (!lib) { printf("Failed\n"); return 1; }

    size_t (*compressBound)(size_t) = dlsym(lib, "ZSTD_compressBound");
    size_t (*compress)(void*, size_t, const void*, size_t, int) = dlsym(lib, "ZSTD_compress");
    size_t (*decompress)(void*, size_t, const void*, size_t) = dlsym(lib, "ZSTD_decompress");
    int (*isError)(size_t) = dlsym(lib, "ZSTD_isError");
    const char* (*getError)(size_t) = dlsym(lib, "ZSTD_getErrorName");

    const char *src = "Hello, World! This is a test of zstd compression.";
    size_t srcSize = strlen(src) + 1;
    size_t dstBound = compressBound(srcSize);

    void *compressed = malloc(dstBound);
    size_t compSize = compress(compressed, dstBound, src, srcSize, 3);
    printf("Compressed %zu bytes to %zu bytes\n", srcSize, compSize);
    if (isError(compSize)) { printf("Error: %s\n", getError(compSize)); return 1; }

    void *decompressed = malloc(srcSize + 10);
    size_t decSize = decompress(decompressed, srcSize + 10, compressed, compSize);
    printf("Decompressed to %zu bytes\n", decSize);
    printf("Result: %s\n", (char*)decompressed);

    free(compressed);
    free(decompressed);
    dlclose(lib);
    return 0;
}
EOF
gcc -o /tmp/test_compress /tmp/test_compress.c -ldl && /tmp/test_compress

