static void print_short_help(const char *progname) {
    fprintf(stderr, "Compress or decompress the INPUT file(s); reads from STDIN if INPUT is `-` or not provided.\n\n");
    fprintf(stderr, "Usage: %s [OPTIONS...] [INPUT... | -] [-o OUTPUT]\n\n", progname);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -o OUTPUT                     Write output to a single file, OUTPUT.\n");
    fprintf(stderr, "  -k, --keep                    Preserve INPUT file(s). [Default] \n");
    fprintf(stderr, "  --rm                          Remove INPUT file(s) after successful (de)compression to file.\n\n");
    fprintf(stderr, "  -#                            Desired compression level, where `#` is a number between 1 and 19;\n");
    fprintf(stderr, "                                lower numbers provide faster compression, higher numbers yield\n");
    fprintf(stderr, "                                better compression ratios. [Default: 3]\n\n");
    fprintf(stderr, "  -d, --decompress              Perform decompression.\n");
    fprintf(stderr, "  -D DICT                       Use DICT as the dictionary for compression or decompression.\n\n");
    fprintf(stderr, "  -f, --force                   Disable input and output checks. Allows overwriting existing files,\n");
    fprintf(stderr, "                                receiving input from the console, printing output to STDOUT, and\n");
    fprintf(stderr, "                                operating on links, block devices, etc. Unrecognized formats will be\n");
    fprintf(stderr, "                                passed-through through as-is.\n\n");
    fprintf(stderr, "  -h                            Display short usage and exit.\n");
    fprintf(stderr, "  -H, --help                    Display full help and exit.\n");
    fprintf(stderr, "  -V, --version                 Display the program version and exit.\n\n");
}

static void print_full_help(const char *progname) {
    print_short_help(progname);
    fprintf(stderr, "Advanced options:\n");
    fprintf(stderr, "  -c, --stdout                  Write to STDOUT (even if it is a console) and keep the INPUT file(s).\n\n");
    fprintf(stderr, "  -v, --verbose                 Enable verbose output; pass multiple times to increase verbosity.\n");
    fprintf(stderr, "  -q, --quiet                   Suppress warnings; pass twice to suppress errors.\n");
    fprintf(stderr, "  --trace LOG                   Log tracing information to LOG.\n\n");
    fprintf(stderr, "  --[no-]progress               Forcibly show/hide the progress counter. NOTE: Any (de)compressed\n");
    fprintf(stderr, "                                output to terminal will mix with progress counter text.\n\n");
    fprintf(stderr, "  -r                            Operate recursively on directories.\n");
    fprintf(stderr, "  --filelist LIST               Read a list of files to operate on from LIST.\n");
    fprintf(stderr, "  --output-dir-flat DIR         Store processed files in DIR.\n");
    fprintf(stderr, "  --output-dir-mirror DIR       Store processed files in DIR, respecting original directory structure.\n");
    fprintf(stderr, "  --[no-]asyncio                Use asynchronous IO. [Default: Enabled]\n\n");
    fprintf(stderr, "  --[no-]check                  Add XXH64 integrity checksums during compression. [Default: Add, Validate]\n");
    fprintf(stderr, "                                If `-d` is present, ignore/validate checksums during decompression.\n\n");
    fprintf(stderr, "  --                            Treat remaining arguments after `--` as files.\n\n");
    fprintf(stderr, "Advanced compression options:\n");
    fprintf(stderr, "  --ultra                       Enable levels beyond 19, up to 22; requires more memory.\n");
    fprintf(stderr, "  --fast[=#]                    Use to very fast compression levels. [Default: 1]\n");
    fprintf(stderr, "  --adapt                       Dynamically adapt compression level to I/O conditions.\n");
    fprintf(stderr, "  --long[=#]                    Enable long distance matching with window log #. [Default: 27]\n");
