#define DEFAULT_COMPRESS_LEVEL 3
#define DEFAULT_DICT_SIZE (112640)
#define MAX_FILES 65536

/* Format types */
#define FMT_ZSTD 0
#define FMT_GZIP 1

/* Verbosity levels */
#define VERB_QUIET  -2
#define VERB_SILENT -1
#define VERB_NORMAL  0
#define VERB_VERBOSE 1

static int g_verbosity = VERB_NORMAL;

/* Print to stderr */
static void print_err(int level, const char *fmt, ...) {
    if (g_verbosity < level) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
}

static void display_progress(const char *srcFileName, unsigned long long srcSize,
                              unsigned long long dstSize, const char *dstFileName) {
    if (g_verbosity < VERB_NORMAL) return;
    /* Format: "filename        :ratio%   (srcSize => dstSize, dstFileName)" */
    double ratio = srcSize ? (double)dstSize * 100.0 / srcSize : 0;

    /* Size formatting helper */
    char srcBuf[32], dstBuf[32];

    auto void fmtSize(unsigned long long sz, char *buf);
    void fmtSize(unsigned long long sz, char *buf) {
        if (sz < 1024) {
            snprintf(buf, 32, "%5llu   B", sz);
        } else if (sz < 1024*1024) {
            snprintf(buf, 32, "%5.3g KiB", (double)sz/1024);
        } else if (sz < 1024ULL*1024*1024) {
            snprintf(buf, 32, "%5.3g MiB", (double)sz/(1024*1024));
        } else {
            snprintf(buf, 32, "%5.3g GiB", (double)sz/(1024ULL*1024*1024));
        }
    }

    fmtSize(srcSize, srcBuf);
    fmtSize(dstSize, dstBuf);

    /* Pad filename to 20 chars */
    char padded[256];
    int namelen = strlen(srcFileName);
    if (namelen > 20) namelen = 20;
    snprintf(padded, sizeof(padded), "%-20.20s", srcFileName);

    fprintf(stderr, "%s :%6.2f%%   (%s => %s, %s) \n",
            padded, ratio, srcBuf, dstBuf, dstFileName);
}

/* Format size for -l output */
static void fmt_size_l(unsigned long long sz, char *buf, int width) {
    if (sz < 1024) {
        snprintf(buf, 32, "%*llu   B", width - 4, sz);
    } else if (sz < 1024*1024) {
        snprintf(buf, 32, "%*.3g KiB", width - 4, (double)sz/1024);
    } else if (sz < 1024ULL*1024*1024) {
        snprintf(buf, 32, "%*.3g MiB", width - 4, (double)sz/(1024*1024));
    } else {
        snprintf(buf, 32, "%*.3g GiB", width - 4, (double)sz/(1024ULL*1024*1024));
    }
}

/* gzip magic numbers */
static const unsigned char GZIP_MAGIC[2] = {0x1f, 0x8b};
static const unsigned char ZSTD_MAGIC[4] = {0x28, 0xb5, 0x2f, 0xfd};

/* Simple gzip decompression using zlib (inflate) */
#include <zlib.h>

static int gzip_decompress_file(FILE *fin, FILE *fout) {
    unsigned char inbuf[65536];
    unsigned char outbuf[65536];
    z_stream strm;
    int ret;

    memset(&strm, 0, sizeof(strm));
    /* 16+MAX_WBITS to handle gzip format */
    ret = inflateInit2(&strm, 16 + MAX_WBITS);
    if (ret != Z_OK) return -1;

    do {
        strm.avail_in = fread(inbuf, 1, sizeof(inbuf), fin);
        if (ferror(fin)) { inflateEnd(&strm); return -1; }
        if (strm.avail_in == 0) break;
        strm.next_in = inbuf;

        do {
            strm.avail_out = sizeof(outbuf);
            strm.next_out = outbuf;
            ret = inflate(&strm, Z_NO_FLUSH);
            if (ret == Z_STREAM_ERROR || ret == Z_NEED_DICT || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR) {
                inflateEnd(&strm);
                return -1;
            }
            size_t have = sizeof(outbuf) - strm.avail_out;
            if (fwrite(outbuf, 1, have, fout) != have) {
                inflateEnd(&strm);
                return -1;
            }
        } while (strm.avail_out == 0);
    } while (ret != Z_STREAM_END);

    inflateEnd(&strm);
    return (ret == Z_STREAM_END) ? 0 : -1;
}

static int gzip_compress_file(FILE *fin, FILE *fout, int level) {
    unsigned char inbuf[65536];
    unsigned char outbuf[65536];
    z_stream strm;
    int ret;
    int flush;

    memset(&strm, 0, sizeof(strm));
    ret = deflateInit2(&strm, level, Z_DEFLATED, 16 + MAX_WBITS, 8, Z_DEFAULT_STRATEGY);
    if (ret != Z_OK) return -1;

    do {
        strm.avail_in = fread(inbuf, 1, sizeof(inbuf), fin);
        if (ferror(fin)) { deflateEnd(&strm); return -1; }
        flush = feof(fin) ? Z_FINISH : Z_NO_FLUSH;
        strm.next_in = inbuf;

        do {
            strm.avail_out = sizeof(outbuf);
            strm.next_out = outbuf;
            ret = deflate(&strm, flush);
            if (ret == Z_STREAM_ERROR) { deflateEnd(&strm); return -1; }
            size_t have = sizeof(outbuf) - strm.avail_out;
            if (fwrite(outbuf, 1, have, fout) != have) {
                deflateEnd(&strm);
                return -1;
            }
        } while (strm.avail_out == 0);
    } while (flush != Z_FINISH);

    deflateEnd(&strm);
    return 0;
}

