    fprintf(stderr, "Compress or decompress the INPUT file(s); reads from STDIN if INPUT is `-` or not provided.\n\n");
    fprintf(stderr, "Usage: %s [OPTIONS...] [INPUT... | -] [-o OUTPUT]\n\n", progname);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -o OUTPUT                     Write output to a single file, OUTPUT.\n");
    fprintf(stderr, "  -k, --keep                    Preserve INPUT file(s). [Default] \n");
    fprintf(stderr, "  --rm                          Remove INPUT file(s) after successful (de)compression to file.\n\n");
    fprintf(stderr, "  -#                            Desired compression level, where `#` is a number between 1 and 19;\n");
    fprintf(stderr, "                                lower numbers provide faster compression, higher numbers yield\n");
    fprintf(stderr, "                                better compression ratios. [Default: 3]\n\n");
    fprintf(stderr, "  -d, --decompress              Perform decompression.\n");
    fprintf(stderr, "  -D DICT                       Use DICT as the dictionary for compression or decompression.\n\n");
    fprintf(stderr, "  -f, --force                   Disable input and output checks. Allows overwriting existing files,\n");
    fprintf(stderr, "                                receiving input from the console, printing output to STDOUT, and\n");
    fprintf(stderr, "                                operating on links, block devices, etc. Unrecognized formats will be\n");
    fprintf(stderr, "                                passed-through through as-is.\n\n");
    fprintf(stderr, "  -h                            Display short usage and exit.\n");
    fprintf(stderr, "  -H, --help                    Display full help and exit.\n");
    fprintf(stderr, "  -V, --version                 Display the program version and exit.\n\n");
}

