/* Get suffix of filename */
static const char *get_suffix(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return "";
    return dot;
}

/* Remove suffix and return base name */
static char *remove_suffix(const char *filename, const char *suffix) {
    size_t flen = strlen(filename);
    size_t slen = strlen(suffix);
    if (flen <= slen) return strdup(filename);
    char *base = strdup(filename);
    base[flen - slen] = '\0';
    return base;
}

/* Get output filename for decompression */
static char *get_decomp_output(const char *input, int *is_known_suffix) {
    const char *suf = get_suffix(input);
    *is_known_suffix = 1;
    if (strcasecmp(suf, ".zst") == 0 || strcasecmp(suf, ".tzst") == 0) {
        return remove_suffix(input, suf);
    } else if (strcasecmp(suf, ".gz") == 0 || strcasecmp(suf, ".tgz") == 0) {
        if (strcasecmp(suf, ".tgz") == 0) {
            return remove_suffix(input, ".tgz");
        }
        return remove_suffix(input, ".gz");
    }
    *is_known_suffix = 0;
    return NULL;
}

/* Load file into memory */
static void *load_file(const char *filename, size_t *size_out) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    void *buf = malloc(sz + 1);
    if (!buf) { fclose(f); return NULL; }
    size_t r = fread(buf, 1, sz, f);
    fclose(f);
    *size_out = r;
    return buf;
}

/* Check if file is a terminal */
static int is_terminal(FILE *f) {
    return isatty(fileno(f));
}

/* Check if file exists */
static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

/* Ask user for overwrite permission */
static int ask_overwrite(const char *filename) {
    if (!is_terminal(stdin) || !is_terminal(stderr)) {
        fprintf(stderr, "zstd: %s already exists; not overwritten  \n \n", filename);
        return 0;
    }
    fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", filename);
    fflush(stderr);
    int c = getchar();
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    if (c == 'y' || c == 'Y') {
        return 1;
    }
    fprintf(stderr, "Not overwritten  \n \n");
    return 0;
}

/* mkdir -p equivalent */
static int mkdirp(const char *path, mode_t mode) {
    char tmp[PATH_MAX];
    char *p;
    size_t len;

    snprintf(tmp, sizeof(tmp), "%s", path);
    len = strlen(tmp);
    if (len > 0 && tmp[len-1] == '/') tmp[len-1] = '\0';

    for (p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, mode);
            *p = '/';
        }
    }
    return mkdir(tmp, mode);
}

/* Get the output path for output-dir-flat */
static char *get_flat_output_path(const char *dir, const char *filename, const char *new_suffix) {
    const char *base = strrchr(filename, '/');
    if (base) base++;
    else base = filename;

    char *result = malloc(strlen(dir) + strlen(base) + strlen(new_suffix) + 10);
    sprintf(result, "%s/%s%s", dir, base, new_suffix);
    return result;
}

/* Get the output path for output-dir-mirror */
static char *get_mirror_output_path(const char *dir, const char *filename, const char *new_suffix) {
    /* Strip leading / */
    const char *rel = filename;
    if (rel[0] == '/') rel++;

    char *result = malloc(strlen(dir) + strlen(rel) + strlen(new_suffix) + 10);
    sprintf(result, "%s/%s%s", dir, rel, new_suffix);
    return result;
}

/* Create parent directories for a path */
static void create_parent_dirs(const char *path) {
    char *p = strdup(path);
    char *dir = dirname(p);
    mkdirp(dir, 0755);
    free(p);
}

/* Format size as human-readable string for compression output */
static void format_size_compress(unsigned long long sz, char *buf, size_t buflen) {
    if (sz < 1024) {
        snprintf(buf, buflen, "%5llu   B", sz);
    } else if (sz < 1024*1024) {
        /* Try to keep 4 significant digits with appropriate unit */
        double d = (double)sz / 1024.0;
        if (d >= 100) snprintf(buf, buflen, "%5.4g KiB", d);
        else if (d >= 10) snprintf(buf, buflen, "%5.4g KiB", d);
        else snprintf(buf, buflen, "%5.4g KiB", d);
    } else if (sz < 1024ULL*1024*1024) {
        double d = (double)sz / (1024.0*1024);
        snprintf(buf, buflen, "%5.4g MiB", d);
    } else {
        double d = (double)sz / (1024.0*1024*1024);
        snprintf(buf, buflen, "%5.4g GiB", d);
    }
}
