/* Display compression progress/result */
static void show_compress_result(const char *src_name, unsigned long long src_size,
                                  unsigned long long dst_size, const char *dst_name) {
    if (g_verbosity < VERB_NORMAL) return;

    char src_buf[32], dst_buf[32];
    format_size_compress(src_size, src_buf, sizeof(src_buf));
    format_size_compress(dst_size, dst_buf, sizeof(dst_buf));

    double ratio = src_size ? (double)dst_size * 100.0 / src_size : 0.0;

    /* Pad filename */
    fprintf(stderr, "%-20.20s :%6.2f%%   (%s => %s, %s) \n",
            src_name, ratio, src_buf, dst_buf, dst_name);
}

/* Show decompress result */
static void show_decompress_result(const char *src_name, unsigned long long dst_size) {
    if (g_verbosity < VERB_NORMAL) return;
    char dst_buf[32];
    format_size_compress(dst_size, dst_buf, sizeof(dst_buf));
    fprintf(stderr, "%-20.20s : %s \n", src_name, dst_buf);
}

/* Global variables for summary */
static int g_num_files_processed = 0;
static int g_num_files_success = 0;
static unsigned long long g_total_src_size = 0;
static unsigned long long g_total_dst_size = 0;
static int g_has_errors = 0;

/* Detect format from file header */
static int detect_format(FILE *f) {
    unsigned char magic[4];
    long pos = ftell(f);
    size_t n = fread(magic, 1, 4, f);
    fseek(f, pos, SEEK_SET);

    if (n >= 2 && magic[0] == GZIP_MAGIC[0] && magic[1] == GZIP_MAGIC[1])
        return FMT_GZIP;
    if (n >= 4 && memcmp(magic, ZSTD_MAGIC, 4) == 0)
        return FMT_ZSTD;
    return -1; /* unknown */
}

/* Detect format from buffer */
static int detect_format_buf(const unsigned char *buf, size_t size) {
    if (size >= 2 && buf[0] == GZIP_MAGIC[0] && buf[1] == GZIP_MAGIC[1])
        return FMT_GZIP;
    if (size >= 4 && memcmp(buf, ZSTD_MAGIC, 4) == 0)
        return FMT_ZSTD;
    return -1;
}

/* Compress one file */
static int compress_file(const char *src_path, const char *dst_path,
                          const Options *opts, ZSTD_CCtx *cctx) {
    FILE *fin = NULL, *fout = NULL;
    int ret = 0;
    int using_stdin = (strcmp(src_path, "-") == 0) || (src_path[0] == '\0');
    int using_stdout = (strcmp(dst_path, "-") == 0) || (dst_path[0] == '\0');

    if (using_stdin) {
        fin = stdin;
    } else {
        fin = fopen(src_path, "rb");
        if (!fin) {
            print_err(VERB_NORMAL, "zstd: can't open %s: %s\n", src_path, strerror(errno));
            return 1;
        }
    }

    if (using_stdout) {
        fout = stdout;
    } else {
        /* Check if output exists */
        if (!opts->force && file_exists(dst_path)) {
            if (!ask_overwrite(dst_path)) {
                if (!using_stdin) fclose(fin);
                return 1;
            }
        }
        fout = fopen(dst_path, "wb");
        if (!fout) {
            print_err(VERB_NORMAL, "zstd: can't create %s: %s\n", dst_path, strerror(errno));
            if (!using_stdin) fclose(fin);
            return 1;
        }
    }

    unsigned long long src_size = 0;
    unsigned long long dst_size = 0;

    if (opts->format == FMT_GZIP) {
        /* Gzip compression */
        int gz_level = opts->compress_level;
        if (gz_level > 9) gz_level = 9;
        if (gz_level < 1) gz_level = 1;

        /* Count input size */
        long start_in = using_stdin ? -1 : ftell(fin);
        ret = gzip_compress_file(fin, fout, gz_level);

        if (!using_stdin) {
            struct stat st;
            stat(src_path, &st);
            src_size = st.st_size;
        }
        if (!using_stdout) {
            struct stat st;
            fflush(fout);
            fstat(fileno(fout), &st);
            dst_size = st.st_size;
        }
    } else {
        /* ZSTD compression - streaming */
        size_t in_buf_size = ZSTD_CStreamInSize();
        size_t out_buf_size = ZSTD_CStreamOutSize();
        void *in_buf = malloc(in_buf_size);
        void *out_buf = malloc(out_buf_size);

        if (!in_buf || !out_buf) {
            ret = 1;
            goto cleanup;
        }

        /* Reset context */
        ZSTD_CCtx_reset(cctx, ZSTD_reset_session_only);

        /* If we know the input size, set it */
        if (!using_stdin) {
            struct stat st;
            if (stat(src_path, &st) == 0) {
                src_size = st.st_size;
                ZSTD_CCtx_setPledgedSrcSize(cctx, src_size);
            }
        }

        size_t remaining;
        do {
            size_t read = fread(in_buf, 1, in_buf_size, fin);
            int is_last = feof(fin) || (read < in_buf_size);
