/* List info about a zstd file */
typedef struct {
    unsigned long long compressed;
    unsigned long long uncompressed;
    int frames;
    int skips;
    unsigned check_type; /* 0=none, 1=xxh64 */
    unsigned long long checksum;
} FileInfo;

static int get_file_info(const char *path, FileInfo *info) {
    memset(info, 0, sizeof(*info));

    FILE *f = fopen(path, "rb");
    if (!f) return -1;

    /* Get compressed size */
    fseek(f, 0, SEEK_END);
    info->compressed = ftell(f);
    fseek(f, 0, SEEK_SET);

    /* Read all data */
    void *data = malloc(info->compressed);
    if (!data) { fclose(f); return -1; }
    fread(data, 1, info->compressed, f);
    fclose(f);

    /* Parse frames */
    unsigned char *p = data;
    size_t remaining = info->compressed;

    while (remaining > 4) {
        /* Check for skippable frame */
        unsigned magic = p[0] | (p[1]<<8) | (p[2]<<16) | (p[3]<<24);
        if ((magic & 0xFFFFFFF0) == 0x184D2A50) {
            /* Skippable frame */
            if (remaining < 8) break;
            unsigned skip_size = p[4] | (p[5]<<8) | (p[6]<<16) | (p[7]<<24);
            info->skips++;
            p += 8 + skip_size;
            if (8 + skip_size > remaining) break;
            remaining -= 8 + skip_size;
            continue;
        }

        if (magic != 0xFD2FB528) break; /* Not ZSTD magic */

        /* Parse frame header */
        ZSTD_frameHeader fh;
        size_t hdr_size = ZSTD_getFrameHeader(&fh, p, remaining);
        if (ZSTD_isError(hdr_size)) break;
        if (hdr_size > 0) break; /* Need more data */

        /* Get this frame's compressed size */
        size_t frame_size = ZSTD_findFrameCompressedSize(p, remaining);
        if (ZSTD_isError(frame_size)) break;

        info->frames++;
        if (fh.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN && 
            fh.frameContentSize != ZSTD_CONTENTSIZE_ERROR) {
            info->uncompressed += fh.frameContentSize;
        } else {
            /* Try to decompress to get size */
            ZSTD_DCtx *dctx = ZSTD_createDCtx();
            void *out = malloc(64*1024*1024); /* 64MB buffer */
            if (out) {
                size_t r = ZSTD_decompress(out, 64*1024*1024, p, frame_size);
                if (!ZSTD_isError(r)) info->uncompressed += r;
                free(out);
            }
            ZSTD_freeDCtx(dctx);
        }

        if (fh.checksumFlag) {
            info->check_type = 1; /* XXH64 */
            /* Checksum is in last 4 bytes of frame */
            if (frame_size >= 4) {
                unsigned char *cs_ptr = p + frame_size - 4;
                info->checksum = cs_ptr[0] | ((unsigned long long)cs_ptr[1]<<8) |
                                 ((unsigned long long)cs_ptr[2]<<16) | ((unsigned long long)cs_ptr[3]<<24);
            }
        }

        p += frame_size;
        if (frame_size > remaining) break;
        remaining -= frame_size;
    }

    free(data);
    return 0;
}

/* Format size for -l listing */
static void fmt_size_list(unsigned long long sz, char *buf, size_t buflen) {
    if (sz < 1024) {
        snprintf(buf, buflen, "%7llu   B", sz);
    } else if (sz < 1024*1024) {
        snprintf(buf, buflen, "%7.4g KiB", (double)sz/1024);
    } else if (sz < 1024ULL*1024*1024) {
        snprintf(buf, buflen, "%7.4g MiB", (double)sz/(1024.0*1024));
    } else {
        snprintf(buf, buflen, "%7.4g GiB", (double)sz/(1024.0*1024*1024));
    }
}

static void print_list_header(void) {
    printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
}

static void print_list_entry(const FileInfo *info, const char *filename) {
    char comp_buf[32], decomp_buf[32];
    fmt_size_list(info->compressed, comp_buf, sizeof(comp_buf));
    fmt_size_list(info->uncompressed, decomp_buf, sizeof(decomp_buf));

    double ratio = info->uncompressed ? (double)info->uncompressed / info->compressed : 0.0;
    const char *check_str = info->check_type ? "XXH64" : " None";

    printf("%6d  %5d  %s  %s  %6.3f  %s  %s\n",
           info->frames, info->skips,
           comp_buf, decomp_buf,
           ratio, check_str, filename);
}

static void print_list_summary(int num_files, const FileInfo *total) {
    char comp_buf[32], decomp_buf[32];
    fmt_size_list(total->compressed, comp_buf, sizeof(comp_buf));
    fmt_size_list(total->uncompressed, decomp_buf, sizeof(decomp_buf));

    double ratio = total->uncompressed ? (double)total->uncompressed / total->compressed : 0.0;
    const char *check_str = total->check_type ? "XXH64" : " None";

    printf("----------------------------------------------------------------- \n");
    char file_label[32];
    snprintf(file_label, sizeof(file_label), "%d files", num_files);
    printf("%6d  %5d  %s  %s  %6.3f  %s  %s\n",
           total->frames, total->skips,
           comp_buf, decomp_buf,
           ratio, check_str, file_label);
}

static int list_file(const char *path) {
    FileInfo info;
