/* Test file integrity */
static int test_file(const char *path, ZSTD_DCtx *dctx) {
    FILE *fin = fopen(path, "rb");
    if (!fin) {
        print_err(VERB_NORMAL, "zstd: can't open %s: %s\n", path, strerror(errno));
        return 1;
    }

    int fmt = detect_format(fin);
    if (fmt < 0) {
        print_err(VERB_NORMAL, "zstd: %s: unsupported format\n", path);
        fclose(fin);
        return 1;
    }

    size_t in_buf_size = ZSTD_DStreamInSize();
    size_t out_buf_size = ZSTD_DStreamOutSize();
    void *in_buf = malloc(in_buf_size);
    void *out_buf = malloc(out_buf_size);

    ZSTD_DCtx_reset(dctx, ZSTD_reset_session_only);

    size_t n;
    unsigned long long total_out = 0;
    int ret = 0;

    while ((n = fread(in_buf, 1, in_buf_size, fin)) > 0) {
        ZSTD_inBuffer input = { in_buf, n, 0 };
        while (input.pos < input.size) {
            ZSTD_outBuffer output = { out_buf, out_buf_size, 0 };
            size_t r = ZSTD_decompressStream(dctx, &output, &input);
            if (ZSTD_isError(r)) {
                print_err(VERB_NORMAL, "zstd: %s: decompression failed: %s\n",
                          path, ZSTD_getErrorName(r));
                ret = 1;
                break;
            }
            total_out += output.pos;
        }
        if (ret) break;
    }

    fclose(fin);
    free(in_buf);
    free(out_buf);

    if (!ret && g_verbosity >= VERB_NORMAL) {
        show_decompress_result(path, total_out);
    }

    return ret;
}

/* Process a list of files (training data) */
static void *load_training_files(char **files, int nfiles,
                                  size_t **sizes_out, unsigned *nsamples_out) {
    /* Calculate total size */
    size_t total = 0;
    size_t *sizes = malloc(nfiles * sizeof(size_t));
    if (!sizes) return NULL;

    for (int i = 0; i < nfiles; i++) {
        struct stat st;
        if (stat(files[i], &st) == 0) {
            sizes[i] = st.st_size;
            total += st.st_size;
        } else {
            sizes[i] = 0;
        }
    }

    void *buf = malloc(total);
    if (!buf) { free(sizes); return NULL; }

    unsigned char *p = buf;
    unsigned nsamp = 0;
    for (int i = 0; i < nfiles; i++) {
        if (sizes[i] == 0) {
            /* Try to load anyway */
            FILE *f = fopen(files[i], "rb");
            if (f) {
                fseek(f, 0, SEEK_END);
                sizes[i] = ftell(f);
                fseek(f, 0, SEEK_SET);
                fread(p, 1, sizes[i], f);
                fclose(f);
                p += sizes[i];
                if (sizes[i] > 0) nsamp++;
            }
        } else {
            FILE *f = fopen(files[i], "rb");
            if (f) {
                size_t r = fread(p, 1, sizes[i], f);
                sizes[i] = r;
                fclose(f);
                p += r;
                if (r > 0) nsamp++;
            }
        }
    }

    *sizes_out = sizes;
    *nsamples_out = nsamp;
    return buf;
}

/* Train dictionary */
static int train_dictionary(Options *opts) {
    if (opts->num_input_files == 0) {
        print_err(VERB_NORMAL, "zstd: no training files provided\n");
        return 1;
    }

    const char *dict_name = opts->output_file ? opts->output_file : "dictionary";
    int maxdict = opts->maxdict ? opts->maxdict : DEFAULT_DICT_SIZE;

    /* Check total size vs dict size */
    size_t total_size = 0;
    for (int i = 0; i < opts->num_input_files; i++) {
        struct stat st;
        if (stat(opts->input_files[i], &st) == 0)
            total_size += st.st_size;
    }

    if (total_size < (size_t)maxdict * 10 && g_verbosity >= VERB_NORMAL) {
        fprintf(stderr, "!  Warning : data size of samples too small for target dictionary size \n");
        fprintf(stderr, "!  Samples should be about 100x larger than target dictionary size \n");
    }

    /* Load files - show progress */
    if (g_verbosity >= VERB_NORMAL && opts->num_input_files > 0) {
        fprintf(stderr, "Loading %s...       \n", opts->input_files[opts->num_input_files > 15 ? 15 : 0]);
        fprintf(stderr, "\n");
        /* Clear line for progress bar */
        fprintf(stderr, "                                                                               \n");
    }

    size_t *sizes = NULL;
    unsigned nsamp = 0;
    void *buf = load_training_files(opts->input_files, opts->num_input_files, &sizes, &nsamp);
    if (!buf) {
        print_err(VERB_NORMAL, "zstd: failed to load training files\n");
        return 1;
    }

    void *dict_buf = malloc(maxdict);
    if (!dict_buf) {
        free(buf); free(sizes);
        return 1;
    }

    size_t dict_size = 0;
    int ret = 0;

    if (opts->train_mode == 3) {
        /* Legacy */
        ZDICT_legacy_params_t params;
        memset(&params, 0, sizeof(params));
        params.selectivityLevel = opts->tlegacy_s ? opts->tlegacy_s : 9;
        params.notificationLevel = (g_verbosity >= VERB_VERBOSE) ? 3 : 2;

        dict_size = ZDICT_trainFromBuffer_legacy(dict_buf, maxdict, buf, sizes, nsamp, params);
    } else if (opts->train_mode == 2) {
        /* Cover */
        ZDICT_cover_params_t params;
        memset(&params, 0, sizeof(params));
        params.k = opts->tk;
        params.d = opts->td;
        params.steps = opts->tsteps ? opts->tsteps : 40;
        params.splitPoint = opts->tsplitd > 0 ? opts->tsplitd : 1.0;
        params.notificationLevel = (g_verbosity >= VERB_VERBOSE) ? 3 : 2;
        if (opts->dictID) params.dictID = opts->dictID;

        dict_size = ZDICT_optimizeTrainFromBuffer_cover(dict_buf, maxdict, buf, sizes, nsamp, &params);
    } else {
        /* FastCover (default) */
        ZDICT_fastCover_params_t params;
        memset(&params, 0, sizeof(params));
        params.k = opts->tk;
        params.d = opts->td;
        params.f = opts->tf ? opts->tf : 20;
        params.steps = opts->tsteps ? opts->tsteps : (opts->train_mode == 1 ? 40 : 5);
        params.accel = opts->taccel ? opts->taccel : 1;
        params.splitPoint = opts->tsplitd > 0 ? opts->tsplitd : 0.75;
        params.notificationLevel = (g_verbosity >= VERB_VERBOSE) ? 3 : 2;
        if (opts->dictID) params.dictID = opts->dictID;

        dict_size = ZDICT_optimizeTrainFromBuffer_fastCover(dict_buf, maxdict, buf, sizes, nsamp, &params);
    }

    if (ZDICT_isError(dict_size)) {
        print_err(VERB_NORMAL, "zstd: dictionary training failed : %s\n", ZDICT_getErrorName(dict_size));
        free(buf); free(sizes); free(dict_buf);
        return 1;
    }

