/* Collect files recursively */
static char **g_recursive_files = NULL;
static int g_recursive_count = 0;
static int g_recursive_cap = 0;

static void add_recursive_file(const char *path) {
    if (g_recursive_count >= g_recursive_cap) {
        g_recursive_cap = g_recursive_cap ? g_recursive_cap * 2 : 64;
        g_recursive_files = realloc(g_recursive_files, g_recursive_cap * sizeof(char*));
    }
    g_recursive_files[g_recursive_count++] = strdup(path);
}

static void collect_files_recursive(const char *dir_path) {
    DIR *d = opendir(dir_path);
    if (!d) return;

    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", dir_path, ent->d_name);

        struct stat st;
        if (stat(full, &st) != 0) continue;

        if (S_ISDIR(st.st_mode)) {
            collect_files_recursive(full);
        } else if (S_ISREG(st.st_mode)) {
            add_recursive_file(full);
        }
    }
    closedir(d);
}

/* Setup compression context with options */
static ZSTD_CCtx *create_cctx(const Options *opts) {
    ZSTD_CCtx *cctx = ZSTD_createCCtx();
    if (!cctx) return NULL;

    int level = opts->compress_level;
    if (opts->fast > 0) {
        level = -opts->fast;  /* negative levels are fast modes */
    }

    ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);
    ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, opts->no_check ? 0 : 1);
    ZSTD_CCtx_setParameter(cctx, ZSTD_c_contentSizeFlag, 1);

    if (opts->no_dictID) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_dictIDFlag, 0);
    }

    if (opts->long_distance) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_enableLongDistanceMatching, 1);
        if (opts->long_window_log > 0)
            ZSTD_CCtx_setParameter(cctx, ZSTD_c_ldmHashLog, opts->long_window_log);
    }

    if (opts->nb_workers > 0) {
        size_t r = ZSTD_CCtx_setParameter(cctx, ZSTD_c_nbWorkers, opts->nb_workers);
        (void)r; /* May not be supported */
    }

    return cctx;
}

