/* Parse number with optional suffix (K, M, G) */
static long long parse_size(const char *s) {
    char *end;
    long long val = strtoll(s, &end, 0);
    if (*end == 'k' || *end == 'K') val *= 1024;
    else if (*end == 'm' || *end == 'M') val *= 1024*1024;
    else if (*end == 'g' || *end == 'G') val *= 1024LL*1024*1024;
    return val;
}

/* Process single file (compress or decompress) */
static int process_file(const char *src, Options *opts,
                         ZSTD_CCtx *cctx, ZSTD_DCtx *dctx) {
    g_num_files_processed++;

