                    opts.train_mode = 0; /* fastcover default */
                    /* Mark as train with fastcover but few steps */
                    opts.train_mode = 99; /* special default train */
                } else if (strncmp(lopt, "train-fastcover", 15) == 0) {
                    opts.train_mode = 1;
                    if (lopt[15] == '=') parse_train_params(lopt+16, &opts);
                } else if (strncmp(lopt, "train-cover", 11) == 0) {
                    opts.train_mode = 2;
                    if (lopt[11] == '=') parse_train_params(lopt+12, &opts);
                } else if (strncmp(lopt, "train-legacy", 12) == 0) {
                    opts.train_mode = 3;
                    if (lopt[12] == '=') parse_train_params(lopt+13, &opts);
                } else if (strncmp(lopt, "fast", 4) == 0) {
                    if (lopt[4] == '=') {
                        opts.fast = atoi(lopt+5);
                        if (opts.fast <= 0) opts.fast = 1;
                    } else {
                        opts.fast = 1;
                    }
                } else if (strncmp(lopt, "long", 4) == 0) {
                    opts.long_distance = 1;
                    if (lopt[4] == '=') {
                        opts.long_window_log = atoi(lopt+5);
                    } else {
                        opts.long_window_log = 27;
                    }
                } else if (strncmp(lopt, "patch-from=", 11) == 0) {
                    opts.patch_from = strdup(lopt+11);
                } else if (strncmp(lopt, "filelist", 8) == 0) {
                    if (lopt[8] == '=') {
                        opts.filelist = strdup(lopt+9);
                    } else if (i+1 < argc) {
                        opts.filelist = strdup(argv[++i]);
                    }
                } else if (strncmp(lopt, "output-dir-flat", 15) == 0) {
                    if (lopt[15] == '=') opts.output_dir_flat = strdup(lopt+16);
                    else if (i+1 < argc) opts.output_dir_flat = strdup(argv[++i]);
                } else if (strncmp(lopt, "output-dir-mirror", 17) == 0) {
                    if (lopt[17] == '=') opts.output_dir_mirror = strdup(lopt+18);
                    else if (i+1 < argc) opts.output_dir_mirror = strdup(argv[++i]);
                } else if (strncmp(lopt, "trace", 5) == 0) {
                    if (lopt[5] == '=') opts.trace_log = strdup(lopt+6);
                    else if (i+1 < argc) opts.trace_log = strdup(argv[++i]);
                } else if (strncmp(lopt, "auto-threads=", 13) == 0) {
                    if (strcmp(lopt+13, "logical") == 0) opts.auto_threads_mode = 1;
                    else opts.auto_threads_mode = 0;
                } else if (strncmp(lopt, "jobsize=", 8) == 0) {
                    opts.job_size = (int)parse_size(lopt+8);
                } else if (strncmp(lopt, "stream-size=", 12) == 0) {
                    opts.stream_size = (int)parse_size(lopt+12);
                } else if (strncmp(lopt, "size-hint=", 10) == 0) {
                    opts.size_hint = parse_size(lopt+10);
                } else if (strncmp(lopt, "target-compressed-block-size=", 29) == 0) {
                    opts.target_block_size = (int)parse_size(lopt+29);
                } else if (strncmp(lopt, "maxdict=", 8) == 0) {
                    opts.maxdict = (int)parse_size(lopt+8);
                } else if (strncmp(lopt, "dictID=", 7) == 0) {
                    opts.dictID = atoi(lopt+7);
                } else if (strncmp(lopt, "memory=", 7) == 0) {
                    /* Memory limit - parse units */
                    opts.memory_mb = (int)(parse_size(lopt+7) / (1024*1024));
                } else if (strncmp(lopt, "format=", 7) == 0) {
                    const char *fmt = lopt+7;
                    if (strcmp(fmt, "zstd") == 0) {
                        opts.format = FMT_ZSTD;
                    } else if (strcmp(fmt, "gzip") == 0 || strcmp(fmt, "gz") == 0) {
                        opts.format = FMT_GZIP;
                    } else {
                        fprintf(stderr, "Incorrect parameter: %s \n", arg);
                        print_short_help(base);
                        return 1;
                    }
                } else if (strcmp(lopt, "mmap-dict") == 0 || strcmp(lopt, "no-mmap-dict") == 0) {
                    /* Ignored - we don't support mmap dict */
                } else {
                    fprintf(stderr, "Incorrect parameter: %s \n", arg);
                    print_short_help(base);
                    return 1;
                }
            } else {
                /* Short options */
                const char *p = arg + 1;
                while (*p) {
                    if (*p == 'd') {
                        opts.decompress = 1;
                        p++;
                    } else if (*p == 'k') {
                        opts.keep = 1;
                        p++;
                    } else if (*p == 'f') {
                        opts.force = 1;
                        p++;
                    } else if (*p == 'c') {
                        opts.stdout_mode = 1;
                        p++;
                    } else if (*p == 'v') {
                        opts.verbose++;
                        g_verbosity = VERB_VERBOSE + (opts.verbose - 1);
                        p++;
                    } else if (*p == 'q') {
                        opts.quiet++;
                        if (opts.quiet == 1) g_verbosity = VERB_SILENT;
                        else g_verbosity = VERB_QUIET;
                        p++;
                    } else if (*p == 'h') {
                        show_help_short = 1;
                        p++;
                    } else if (*p == 'H') {
                        show_help_full = 1;
                        p++;
                    } else if (*p == 'V') {
                        show_version = 1;
                        p++;
                    } else if (*p == 'r') {
                        opts.recursive = 1;
                        p++;
                    } else if (*p == 'l') {
                        opts.list_mode = 1;
                        p++;
                    } else if (*p >= '1' && *p <= '9') {
                        int level = atoi(p);
                        /* Skip all digits */
                        while (*p >= '0' && *p <= '9') p++;
                        if (!opts.ultra && level > 19) {
                            print_err(VERB_NORMAL, "Warning : compression level higher than max, reduced to 19 \n");
                            level = 19;
                        }
                        opts.compress_level = level;
                    } else if (*p == 'o') {
                        p++;
                        if (*p) {
                            opts.output_file = strdup(p);
                            p = p + strlen(p);
                        } else if (i+1 < argc) {
                            opts.output_file = strdup(argv[++i]);
                        }
                    } else if (*p == 'D') {
                        p++;
                        if (*p) {
                            opts.dict_file = strdup(p);
                            p = p + strlen(p);
                        } else if (i+1 < argc) {
                            opts.dict_file = strdup(argv[++i]);
                        }
                    } else if (*p == 'T') {
                        p++;
                        if (*p) {
                            opts.nb_workers = atoi(p);
                            while (*p >= '0' && *p <= '9') p++;
                        } else if (i+1 < argc) {
                            opts.nb_workers = atoi(argv[++i]);
                        }
                    } else if (*p == 'M') {
                        p++;
                        if (*p) {
                            long long mem = parse_size(p);
                            opts.memory_mb = (int)(mem / (1024*1024));
                            while (*p && *p != ' ') p++;
                        } else if (i+1 < argc) {
                            long long mem = parse_size(argv[++i]);
                            opts.memory_mb = (int)(mem / (1024*1024));
                        }
                    } else {
                        fprintf(stderr, "Incorrect parameter: -%c \n", *p);
                        print_short_help(base);
                        return 1;
                    }
                }
            }
        } else {
            /* Input file */
            if (num_input_files < MAX_FILES)
                input_files[num_input_files++] = strdup(arg);
        }
    }

    /* Handle verbose - print version header */
    if (g_verbosity >= VERB_VERBOSE) {
        print_version();
    }

    if (show_version) {
        print_version();
        return 0;
    }

    if (show_help_full) {
        print_full_help(base);
        return 0;
    }

    if (show_help_short) {
        print_short_help(base);
        return 0;
    }

    /* Load filelist if specified */
    if (opts.filelist) {
        FILE *fl = fopen(opts.filelist, "r");
        if (!fl) {
            print_err(VERB_NORMAL, "zstd: can't open filelist %s: %s\n",
                      opts.filelist, strerror(errno));
        } else {
            char line[PATH_MAX];
            while (fgets(line, sizeof(line), fl)) {
                int len = strlen(line);
                while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r'))
                    line[--len] = '\0';
                if (len > 0 && num_input_files < MAX_FILES)
                    input_files[num_input_files++] = strdup(line);
            }
            fclose(fl);
        }
    }

    opts.input_files = input_files;
    opts.num_input_files = num_input_files;

    /* Handle training mode */
    if (opts.train_mode != 0) {
        /* train_mode 99 = default (fastcover with few steps) */
        if (opts.train_mode == 99) opts.train_mode = 0; /* fastcover */
        return train_dictionary(&opts);
    }

    /* Expand directories if recursive */
    char **final_files = input_files;
    int final_count = num_input_files;

    if (opts.recursive) {
        g_recursive_count = 0;
        for (int j = 0; j < num_input_files; j++) {
            struct stat st;
            if (stat(input_files[j], &st) == 0 && S_ISDIR(st.st_mode)) {
                collect_files_recursive(input_files[j]);
            } else {
                add_recursive_file(input_files[j]);
            }
        }
        final_files = g_recursive_files;
        final_count = g_recursive_count;
    }

    /* If no input files, read from stdin */
    if (final_count == 0) {
        /* Check if stdin is terminal and not forced */
        if (!opts.force && is_terminal(stdin)) {
            print_err(VERB_NORMAL, "zstd: refusing to read from a console for stdin. Use -f to force.\n");
            return 1;
        }
        if (!opts.force && !opts.stdout_mode && is_terminal(stdout) && !opts.decompress) {
            print_err(VERB_NORMAL, "zstd: refusing to write to console. Use -c to force.\n");
            return 1;
        }
        /* stdin -> stdout */
        final_files = (char*[]){"-"};
        final_count = 1;
    }

    /* Set up contexts */
    ZSTD_CCtx *cctx = NULL;
    ZSTD_DCtx *dctx = NULL;

    if (!opts.decompress && !opts.test_mode && !opts.list_mode) {
        cctx = create_cctx(&opts);
        if (!cctx) {
            print_err(VERB_NORMAL, "zstd: failed to create compression context\n");
            return 1;
        }
    } else {
        dctx = ZSTD_createDCtx();
        if (!dctx) {
            print_err(VERB_NORMAL, "zstd: failed to create decompression context\n");
            return 1;
        }
        if (opts.memory_mb > 0) {
            ZSTD_DCtx_setParameter(dctx, ZSTD_d_windowLogMax, 
                                    (int)(opts.memory_mb * 1024LL * 1024));
        }
    }

    /* Load dictionary if specified */
    void *dict_data = NULL;
    size_t dict_size = 0;
    ZSTD_CDict *cdict = NULL;
    ZSTD_DDict *ddict = NULL;

    if (opts.dict_file) {
        dict_data = load_dict(opts.dict_file, &dict_size);
        if (!dict_data) {
            print_err(VERB_NORMAL, "zstd: can't load dictionary %s: %s\n",
                      opts.dict_file, strerror(errno));
            if (cctx) ZSTD_freeCCtx(cctx);
            if (dctx) ZSTD_freeDCtx(dctx);
            return 1;
        }
        if (cctx) {
            ZSTD_CCtx_loadDictionary(cctx, dict_data, dict_size);
        }
        if (dctx) {
            ZSTD_DCtx_loadDictionary(dctx, dict_data, dict_size);
        }
    }

    /* List mode: print header first */
    if (opts.list_mode) {
        print_list_header();
    }

    /* Process all files */
    int global_ret = 0;
    FileInfo list_total;
    memset(&list_total, 0, sizeof(list_total));
    int list_count = 0;

    for (int j = 0; j < final_count; j++) {
        const char *src = final_files[j];

        if (opts.list_mode) {
            FileInfo info;
            if (get_file_info(src, &info) == 0) {
                print_list_entry(&info, src);
                list_total.compressed += info.compressed;
                list_total.uncompressed += info.uncompressed;
                list_total.frames += info.frames;
                list_total.skips += info.skips;
                if (info.check_type) list_total.check_type = info.check_type;
                list_count++;
            } else {
                global_ret = 1;
            }
            continue;
        }

        int ret = process_file(src, &opts, cctx, dctx);
        if (ret) {
            global_ret = 1;
            g_has_errors = 1;
        }
    }

    /* Print list summary if multiple files */
    if (opts.list_mode && list_count > 1) {
        print_list_summary(list_count, &list_total);
    }

    /* Print summary for multiple files */
    if (!opts.list_mode && !opts.test_mode && final_count > 1 && g_verbosity >= VERB_NORMAL) {
        if (opts.decompress) {
            /* No summary for decompression typically */
        } else {
            /* Show compression summary */
            char src_buf[32], dst_buf[32];
            format_size_compress(g_total_src_size, src_buf, sizeof(src_buf));
            format_size_compress(g_total_dst_size, dst_buf, sizeof(dst_buf));
            double ratio = g_total_src_size ? (double)g_total_dst_size * 100.0 / g_total_src_size : 0.0;
            fprintf(stderr, "  %d files compressed : %6.2f%% (%s => %s)\n",
                    g_num_files_success, ratio, src_buf, dst_buf);
        }
    }

    /* Cleanup */
    if (cctx) ZSTD_freeCCtx(cctx);
    if (dctx) ZSTD_freeDCtx(dctx);
    if (cdict) ZSTD_freeCDict(cdict);
    if (ddict) ZSTD_freeDDict(ddict);
    free(dict_data);

    return global_ret;
}
