}

static int ask_overwrite(const char *filename) {
    if (!is_terminal(stdin) || !is_terminal(stderr)) {
        fprintf(stderr, "zstd: %s already exists; not overwritten  \n \n", filename);
        return 0;
    }
    fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", filename);
    fflush(stderr);
    int c = getchar();
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    if (c == 'y' || c == 'Y') return 1;
    fprintf(stderr, "Not overwritten  \n \n");
    return 0;
}

static int mkdirp(const char *path, mode_t mode) {
    char tmp[PATH_MAX];
    char *p;
    snprintf(tmp, sizeof(tmp), "%s", path);
    size_t len = strlen(tmp);
    if (len > 0 && tmp[len-1] == '/') tmp[len-1] = '\0';
    for (p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, mode);
            *p = '/';
        }
    }
    return mkdir(tmp, mode);
}

static void create_parent_dirs(const char *path) {
    char *p = strdup(path);
    char *d = dirname(p);
    mkdirp(d, 0755);
    free(p);
}

static int detect_format(FILE *f) {
    unsigned char magic[4];
    long pos = ftell(f);
    size_t n = fread(magic, 1, 4, f);
    fseek(f, pos, SEEK_SET);
    if (n >= 2 && magic[0] == GZIP_MAGIC[0] && magic[1] == GZIP_MAGIC[1]) return FMT_GZIP;
    if (n >= 4 && memcmp(magic, ZSTD_MAGIC, 4) == 0) return FMT_ZSTD;
    return -1;
}

static const char *get_suffix(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return "";
    return dot;
}

static char *remove_suffix(const char *filename, const char *suffix) {
    size_t flen = strlen(filename);
    size_t slen = strlen(suffix);
    char *base = strdup(filename);
    if (flen > slen) base[flen - slen] = '\0';
    return base;
}

static char *get_decomp_output(const char *input, int *is_known_suffix) {
    const char *suf = get_suffix(input);
    *is_known_suffix = 1;
    if (strcasecmp(suf, ".zst") == 0 || strcasecmp(suf, ".tzst") == 0) {
        return remove_suffix(input, suf);
    } else if (strcasecmp(suf, ".gz") == 0) {
        return remove_suffix(input, ".gz");
    } else if (strcasecmp(suf, ".tgz") == 0) {
        return remove_suffix(input, ".tgz");
    }
    *is_known_suffix = 0;
    return NULL;
}

static void *load_file(const char *filename, size_t *size_out) {
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return NULL; }
    void *buf = malloc(sz + 1);
    if (!buf) { fclose(f); return NULL; }
    *size_out = fread(buf, 1, sz, f);
    fclose(f);
    return buf;
}

static long long parse_size(const char *s) {
    char *end;
    long long val = strtoll(s, &end, 0);
    if (*end == 'k' || *end == 'K') val *= 1024;
    else if (*end == 'm' || *end == 'M') val *= 1024*1024;
    else if (*end == 'g' || *end == 'G') val *= 1024LL*1024*1024;
    return val;
}

