    if (n >= 2 && magic[0] == GZIP_MAGIC[0] && magic[1] == GZIP_MAGIC[1]) return FMT_GZIP;
    if (n >= 4 && memcmp(magic, ZSTD_MAGIC, 4) == 0) return FMT_ZSTD;
