            }
            size_t have = sizeof(outbuf) - strm.avail_out;
            if (fwrite(outbuf, 1, have, fout) != have) { inflateEnd(&strm); return -1; }
        } while (strm.avail_out == 0);
    } while (ret != Z_STREAM_END);
    inflateEnd(&strm);
