typedef struct {
    unsigned long long compressed;
    unsigned long long uncompressed;
    int frames;
    int skips;
    int check_type; /* 0=none, 1=xxh64 */
} FileInfo;

static int get_file_info(const char *path, FileInfo *info) {
    memset(info, 0, sizeof(*info));
    FILE *f = fopen(path, "rb");
    if (!f) return -1;
    fseek(f, 0, SEEK_END);
    long fsz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (fsz < 0) { fclose(f); return -1; }
    info->compressed = fsz;

    /* Read data to parse frames */
    unsigned char *data = malloc(fsz);
    if (!data) { fclose(f); return -1; }
    if (fread(data, 1, fsz, f) != (size_t)fsz) { fclose(f); free(data); return -1; }
    fclose(f);

    unsigned char *p = data;
    size_t remaining = fsz;

    while (remaining >= 4) {
        unsigned magic = p[0] | (p[1]<<8) | (p[2]<<16) | (p[3]<<24);

        /* Skippable frame */
        if ((magic & 0xFFFFFFF0U) == 0x184D2A50U) {
            if (remaining < 8) break;
            unsigned skip_size = p[4] | (p[5]<<8) | (p[6]<<16) | (p[7]<<24);
            info->skips++;
            size_t total_skip = 8 + skip_size;
            if (total_skip > remaining) break;
            p += total_skip; remaining -= total_skip;
            continue;
        }

        if (magic != 0xFD2FB528U) break; /* Not ZSTD magic */

        ZSTD_frameHeader fh;
        size_t hdr_r = ZSTD_getFrameHeader(&fh, p, remaining);
        if (ZSTD_isError(hdr_r) || hdr_r > 0) break;

        size_t frame_size = ZSTD_findFrameCompressedSize(p, remaining);
        if (ZSTD_isError(frame_size)) break;

        info->frames++;
        if (fh.checksumFlag) info->check_type = 1;

        if (fh.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN &&
            fh.frameContentSize != ZSTD_CONTENTSIZE_ERROR) {
            info->uncompressed += fh.frameContentSize;
        } else {
            /* Decompress to find size */
            ZSTD_DCtx *dctx = ZSTD_createDCtx();
            size_t obuf_sz = 16*1024*1024;
            void *obuf = NULL;
            unsigned long long total = 0;
            /* Use streaming to avoid huge allocation */
            ZSTD_inBuffer input = { p, frame_size, 0 };
            obuf_sz = ZSTD_DStreamOutSize();
            obuf = malloc(obuf_sz);
            if (obuf) {
                ZSTD_DCtx_reset(dctx, ZSTD_reset_session_only);
                while (input.pos < input.size) {
                    ZSTD_outBuffer output = { obuf, obuf_sz, 0 };
                    size_t r = ZSTD_decompressStream(dctx, &output, &input);
                    if (ZSTD_isError(r)) break;
                    total += output.pos;
                }
                free(obuf);
            }
            ZSTD_freeDCtx(dctx);
            info->uncompressed += total;
        }

        p += frame_size;
        if (frame_size > remaining) break;
        remaining -= frame_size;
    }

    free(data);
    return 0;
}

