/* Recursive file collection */
static char **g_rec_files = NULL;
static int g_rec_count = 0;
static int g_rec_cap = 0;

static void rec_add(const char *path) {
    if (g_rec_count >= g_rec_cap) {
        g_rec_cap = g_rec_cap ? g_rec_cap * 2 : 64;
        g_rec_files = realloc(g_rec_files, g_rec_cap * sizeof(char*));
    }
    g_rec_files[g_rec_count++] = strdup(path);
}

static void collect_recursive(const char *dir) {
    DIR *d = opendir(dir);
    if (!d) return;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (!strcmp(ent->d_name,".") || !strcmp(ent->d_name,"..")) continue;
        char full[PATH_MAX];
        snprintf(full, sizeof(full), "%s/%s", dir, ent->d_name);
        struct stat st;
        if (stat(full, &st)) continue;
        if (S_ISDIR(st.st_mode)) collect_recursive(full);
        else if (S_ISREG(st.st_mode)) rec_add(full);
    }
    closedir(d);
}

static void *load_training_files(char **files, int nfiles, size_t **sizes_out, unsigned *nsamp_out) {
    size_t total = 0;
    size_t *sizes = calloc(nfiles, sizeof(size_t));
    if (!sizes) return NULL;
    for (int i = 0; i < nfiles; i++) {
        struct stat st;
        if (!stat(files[i], &st)) { sizes[i] = st.st_size; total += st.st_size; }
    }
    void *buf = malloc(total + 1);
    if (!buf) { free(sizes); return NULL; }
    unsigned char *p = buf;
    unsigned nsamp = 0;
    for (int i = 0; i < nfiles; i++) {
        if (sizes[i] == 0) continue;
        FILE *f = fopen(files[i], "rb");
        if (!f) { sizes[i] = 0; continue; }
        size_t r = fread(p, 1, sizes[i], f);
        fclose(f);
        sizes[i] = r;
        p += r;
        if (r > 0) nsamp++;
    }
    *sizes_out = sizes;
    *nsamp_out = nsamp;
    return buf;
}

static int train_dictionary(Options *opts) {
    if (opts->num_input_files == 0) {
        fprintf(stderr, "zstd: no training files provided\n");
        return 1;
    }
    const char *dict_name = opts->output_file ? opts->output_file : "dictionary";
    int maxdict = opts->maxdict ? opts->maxdict : DEFAULT_DICT_SIZE;

    /* Warning for small data */
    size_t total_size = 0;
    for (int i = 0; i < opts->num_input_files; i++) {
        struct stat st;
        if (!stat(opts->input_files[i], &st)) total_size += st.st_size;
    }
    if (total_size < (size_t)maxdict * 10) {
        fprintf(stderr, "!  Warning : data size of samples too small for target dictionary size \n");
        fprintf(stderr, "!  Samples should be about 100x larger than target dictionary size \n");
    }

    /* Show loading progress - show the 17th file (index 16) or first if <17 */
    int show_idx = opts->num_input_files > 16 ? 16 : 0;
    fprintf(stderr, "Loading %s...       \n\n", opts->input_files[show_idx]);
    fprintf(stderr, "                                                                               \n");

    size_t *sizes = NULL;
    unsigned nsamp = 0;
    void *buf = load_training_files(opts->input_files, opts->num_input_files, &sizes, &nsamp);
    if (!buf) { fprintf(stderr,"zstd: failed to load training files\n"); return 1; }

    void *dict_buf = malloc(maxdict);
    if (!dict_buf) { free(buf); free(sizes); return 1; }

    size_t dict_size = 0;

    if (opts->train_mode == 3) {
        ZDICT_legacy_params_t params;
        memset(&params, 0, sizeof(params));
        params.selectivityLevel = opts->tlegacy_s ? opts->tlegacy_s : 9;
        params.notificationLevel = 2;
        fprintf(stderr, "\n");
        fprintf(stderr, "                                                                      \n");
        fprintf(stderr, "sorting %d files of total size %d MB ...\n", nsamp, (int)(total_size/1048576));
        fprintf(stderr, "finding patterns ... \n");
        dict_size = ZDICT_trainFromBuffer_legacy(dict_buf, maxdict, buf, sizes, nsamp, params);
    } else if (opts->train_mode == 2) {
        /* Cover */
        ZDICT_cover_params_t params;
        memset(&params, 0, sizeof(params));
        params.k = opts->tk;
        params.d = opts->td;
        params.steps = opts->tsteps ? opts->tsteps : 40;
        params.splitPoint = opts->tsplitd > 0 ? opts->tsplitd : 1.0;
        params.notificationLevel = 2;
        if (opts->dictID) params.dictID = opts->dictID;
        dict_size = ZDICT_optimizeTrainFromBuffer_cover(dict_buf, maxdict, buf, sizes, nsamp, &params);
    } else {
        /* FastCover (train_mode 0=default with few steps, 1=full fastcover) */
        ZDICT_fastCover_params_t params;
        memset(&params, 0, sizeof(params));
        params.k = opts->tk;
        params.d = opts->td;
        params.f = opts->tf ? opts->tf : 20;
