            ZSTD_CCtx_setParameter(cctx, ZSTD_c_ldmHashLog, opts->long_window_log);
    }
    if (opts->nb_workers > 0)
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_nbWorkers, opts->nb_workers); /* may fail silently */
    return cctx;
