/* Get output path for compression */
static char *get_comp_dst(const char *src, const Options *opts) {
    if (opts->output_file) return strdup(opts->output_file);
    if (opts->stdout_mode) return strdup("-");

    const char *suffix = (opts->format == FMT_GZIP) ? ".gz" : ".zst";

    if (opts->output_dir_flat) {
        const char *base = strrchr(src, '/');
        if (base) base++; else base = src;
        char *r = malloc(strlen(opts->output_dir_flat) + strlen(base) + strlen(suffix) + 5);
        sprintf(r, "%s/%s%s", opts->output_dir_flat, base, suffix);
        mkdirp(opts->output_dir_flat, 0755);
        return r;
    }
    if (opts->output_dir_mirror) {
        const char *rel = src;
        if (rel[0] == '/') rel++;
        char *r = malloc(strlen(opts->output_dir_mirror) + strlen(rel) + strlen(suffix) + 5);
        sprintf(r, "%s/%s%s", opts->output_dir_mirror, rel, suffix);
        create_parent_dirs(r);
        return r;
    }

    char *r = malloc(strlen(src) + strlen(suffix) + 5);
    sprintf(r, "%s%s", src, suffix);
    return r;
}

/* Get output path for decompression */
static char *get_decomp_dst(const char *src, const Options *opts) {
    if (opts->output_file) return strdup(opts->output_file);
    if (opts->stdout_mode) return strdup("-");

    int known;
    char *base_path = get_decomp_output(src, &known);
    if (!known) {
        if (!opts->force) {
            fprintf(stderr, "zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n", src);
            return NULL;
        }
        free(base_path);
        base_path = strdup(src);
    }

    if (opts->output_dir_flat) {
        const char *bname = strrchr(base_path, '/');
        if (bname) bname++; else bname = base_path;
        char *r = malloc(strlen(opts->output_dir_flat) + strlen(bname) + 5);
        sprintf(r, "%s/%s", opts->output_dir_flat, bname);
        mkdirp(opts->output_dir_flat, 0755);
        free(base_path);
        return r;
    }
    if (opts->output_dir_mirror) {
        const char *rel = base_path;
        if (rel[0] == '/') rel++;
        char *r = malloc(strlen(opts->output_dir_mirror) + strlen(rel) + 5);
        sprintf(r, "%s/%s", opts->output_dir_mirror, rel);
        create_parent_dirs(r);
        free(base_path);
        return r;
    }

    return base_path;
}

static int process_file(const char *src, const Options *opts,
                         ZSTD_CCtx *cctx, ZSTD_DCtx *dctx) {
    if (opts->test_mode) return test_file(src, dctx);

    if (opts->decompress) {
        char *dst = get_decomp_dst(src, opts);
        if (!dst && !opts->force) return 1;
        if (!dst) dst = strdup("-");
        int ret = decompress_file(src, dst, opts, dctx);
        free(dst);
        if (!ret && !opts->keep && strcmp(src, "-") != 0) unlink(src);
        return ret;
    } else {
        if (opts->exclude_compressed) {
            FILE *f = fopen(src, "rb");
            if (f) {
                int fmt = detect_format(f); fclose(f);
                if (fmt >= 0) { if (g_verbosity >= VERB_VERBOSE) fprintf(stderr,"zstd: %s already compressed, skipping\n",src); return 0; }
            }
        }
        char *dst = get_comp_dst(src, opts);
        int ret = compress_file(src, dst, opts, cctx);
        free(dst);
        if (!ret && !opts->keep && strcmp(src, "-") != 0) unlink(src);
        return ret;
    }
}

