                else if (!strcmp(lo,"no-pass-through")) opts.pass_through = 0;
                else if (!strcmp(lo,"compress-literals")) opts.compress_literals = 1;
                else if (!strcmp(lo,"no-compress-literals")) opts.no_compress_literals = 1;
