                    else if (*p=='H') { show_help_full=1; p++; }
                    else if (*p=='V') { show_version=1; p++; }
                    else if (*p=='r') { opts.recursive=1; p++; }
                    else if (*p=='l') { opts.list_mode=1; p++; }
