                    }
                    else { fprintf(stderr,"Incorrect parameter: -%c \n",*p); print_short_help(base); return 1; }
                }
            }
        } else {
            if (num_input_files < MAX_FILES) input_files[num_input_files++] = strdup(arg);
        }
    }

    if (g_verbosity >= VERB_VERBOSE) print_version();
    if (show_version) { print_version(); return 0; }
    if (show_help_full) { print_full_help(base); return 0; }
    if (show_help_short) { print_short_help(base); return 0; }

    /* Load filelist */
    if (opts.filelist) {
