    char **final_files = input_files;
    int final_count = num_input_files;

    if (opts.recursive) {
        g_rec_count = 0;
        for (int j = 0; j < num_input_files; j++) {
            struct stat st;
            if (!stat(input_files[j], &st) && S_ISDIR(st.st_mode)) collect_recursive(input_files[j]);
