    ZSTD_CCtx *cctx = NULL;
    ZSTD_DCtx *dctx = NULL;

    if (!opts.decompress && !opts.test_mode && !opts.list_mode) {
        cctx = create_cctx(&opts);
        if (!cctx) { fprintf(stderr,"zstd: failed to create compression context\n"); return 1; }
    } else {
        dctx = ZSTD_createDCtx();
        if (!dctx) { fprintf(stderr,"zstd: failed to create decompression context\n"); return 1; }
    }

    /* Load dictionary */
    void *dict_data = NULL;
    size_t dict_size = 0;
    if (opts.dict_file) {
        dict_data = load_file(opts.dict_file, &dict_size);
        if (!dict_data) {
            fprintf(stderr,"zstd: can't load dictionary %s: %s\n",opts.dict_file,strerror(errno));
            if (cctx) ZSTD_freeCCtx(cctx);
            if (dctx) ZSTD_freeDCtx(dctx);
            return 1;
        }
        if (cctx) ZSTD_CCtx_loadDictionary(cctx, dict_data, dict_size);
        if (dctx) ZSTD_DCtx_loadDictionary(dctx, dict_data, dict_size);
    }

    if (opts.list_mode) print_list_header();

    int global_ret = 0;
    FileInfo list_total; memset(&list_total, 0, sizeof(list_total));
    int list_count = 0;

    for (int j = 0; j < final_count; j++) {
        const char *src = final_files[j];

        if (opts.list_mode) {
            FileInfo info;
            if (!get_file_info(src, &info)) {
                print_list_entry(&info, src);
                list_total.compressed += info.compressed;
                list_total.uncompressed += info.uncompressed;
                list_total.frames += info.frames;
                list_total.skips += info.skips;
                if (info.check_type) list_total.check_type = info.check_type;
                list_count++;
            } else {
                global_ret = 1;
            }
            continue;
        }

        int ret = process_file(src, &opts, cctx, dctx);
        if (ret) global_ret = 1;
    }

    if (opts.list_mode && list_count > 1)
        print_list_summary(list_count, &list_total);

    /* Multi-file compression summary */
    if (!opts.list_mode && !opts.test_mode && !opts.decompress &&
        g_num_files_success > 1 && g_verbosity >= VERB_NORMAL) {
        char src_buf[32], dst_buf[32];
        fmt_size_6(g_total_src_size, src_buf, sizeof(src_buf));
        fmt_size_6(g_total_dst_size, dst_buf, sizeof(dst_buf));
        double ratio = g_total_src_size ? (double)g_total_dst_size*100.0/g_total_src_size : 0.0;
        fprintf(stderr, "  %d files compressed : %6.2f%% (%s => %s)\n",
                g_num_files_success, ratio, src_buf, dst_buf);
    }

    if (cctx) ZSTD_freeCCtx(cctx);
    if (dctx) ZSTD_freeDCtx(dctx);
    free(dict_data);
    return global_ret;
}
