static int gzip_decompress_file(FILE *fin, FILE *fout) {
    unsigned char in[65536], out[65536];
    z_stream s; int r;
    memset(&s, 0, sizeof(s));
    if (inflateInit2(&s, 16 + MAX_WBITS) != Z_OK) return -1;
    do {
        s.avail_in = fread(in, 1, sizeof(in), fin);
        if (ferror(fin)) { inflateEnd(&s); return -1; }
        if (!s.avail_in) break;
        s.next_in = in;
