            s.avail_out = sizeof(out); s.next_out = out;
            r = inflate(&s, Z_NO_FLUSH);
            if (r == Z_STREAM_ERROR || r == Z_NEED_DICT || r == Z_DATA_ERROR || r == Z_MEM_ERROR) { inflateEnd(&s); return -1; }
