    char *e; long long v = strtoll(s, &e, 0);
    if (*e=='k'||*e=='K') v*=1024;
    else if (*e=='m'||*e=='M') v*=1024*1024;
    else if (*e=='g'||*e=='G') v*=1024LL*1024*1024;
    return v;
}
