static int is_terminal(FILE *f) { return isatty(fileno(f)); }

static int file_exists(const char *path) {
    struct stat st; return stat(path, &st) == 0;
}

static int ask_overwrite(const char *filename) {
    if (!is_terminal(stdin) || !is_terminal(stderr)) {
        fprintf(stderr, "zstd: %s already exists; not overwritten  \n \n", filename);
        return 0;
    }
    fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", filename);
    fflush(stderr);
    int c = getchar(), ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    if (c == 'y' || c == 'Y') return 1;
    fprintf(stderr, "Not overwritten  \n \n");
    return 0;
}

static int mkdirp(const char *path, mode_t mode) {
    char tmp[PATH_MAX]; char *p;
    snprintf(tmp, sizeof(tmp), "%s", path);
    size_t len = strlen(tmp);
    if (len > 0 && tmp[len-1] == '/') tmp[len-1] = '\0';
    for (p = tmp + 1; *p; p++) {
        if (*p == '/') { *p = '\0'; mkdir(tmp, mode); *p = '/'; }
    }
    return mkdir(tmp, mode);
}

static void create_parent_dirs(const char *path) {
    char *p = strdup(path);
    mkdirp(dirname(p), 0755);
    free(p);
}

static int detect_format(FILE *f) {
    unsigned char m[4]; long pos = ftell(f);
    size_t n = fread(m, 1, 4, f); fseek(f, pos, SEEK_SET);
    if (n >= 2 && m[0] == GZIP_MAGIC[0] && m[1] == GZIP_MAGIC[1]) return FMT_GZIP;
    if (n >= 4 && !memcmp(m, ZSTD_MAGIC, 4)) return FMT_ZSTD;
    return -1;
}

static const char *get_suffix(const char *f) {
    const char *d = strrchr(f, '.'); return d ? d : "";
}

static char *remove_suffix(const char *f, const char *s) {
    size_t fl = strlen(f), sl = strlen(s);
    char *r = strdup(f);
    if (fl > sl) r[fl-sl] = '\0';
    return r;
}

static char *get_decomp_output(const char *in, int *known) {
    const char *s = get_suffix(in);
    *known = 1;
    if (!strcasecmp(s,".zst") || !strcasecmp(s,".tzst")) return remove_suffix(in, s);
    if (!strcasecmp(s,".gz")) return remove_suffix(in, ".gz");
    if (!strcasecmp(s,".tgz")) return remove_suffix(in, ".tgz");
    *known = 0; return NULL;
}

static void *load_file(const char *fn, size_t *sz) {
    FILE *f = fopen(fn, "rb"); if (!f) return NULL;
    fseek(f, 0, SEEK_END); long s = ftell(f); fseek(f, 0, SEEK_SET);
    if (s < 0) { fclose(f); return NULL; }
    void *b = malloc(s+1); if (!b) { fclose(f); return NULL; }
    *sz = fread(b, 1, s, f); fclose(f); return b;
}

static long long parse_size(const char *s) {
    char *e; long long v = strtoll(s, &e, 0);
    if (*e=='k'||*e=='K') v*=1024;
    else if (*e=='m'||*e=='M') v*=1024*1024;
    else if (*e=='g'||*e=='G') v*=1024LL*1024*1024;
    return v;
}
