    } else {
        size_t in_sz = ZSTD_CStreamInSize(), out_sz = ZSTD_CStreamOutSize();
        void *ib = malloc(in_sz), *ob = malloc(out_sz);
        if (!ib || !ob) { free(ib); free(ob); ret=1; goto cclean; }
        ZSTD_CCtx_reset(cctx, ZSTD_reset_session_only);
        if (!is_stdin) { struct stat st; if(!stat(src,&st)) { src_sz=st.st_size; ZSTD_CCtx_setPledgedSrcSize(cctx,src_sz); } }
        int done = 0;
        while (!done) {
            size_t n = fread(ib, 1, in_sz, fin);
            if (ferror(fin)) { ret=1; break; }
            int last = feof(fin) || n < in_sz; done = last;
            ZSTD_EndDirective eo = last ? ZSTD_e_end : ZSTD_e_continue;
            ZSTD_inBuffer inp = {ib, n, 0};
