                ZSTD_outBuffer outp = {ob, out_sz, 0};
                size_t r = ZSTD_compressStream2(cctx, &outp, &inp, eo);
                if (ZSTD_isError(r)) {
                    fprintf(stderr, "zstd: compression error: %s\n", ZSTD_getErrorName(r));
                    ret=1; break;
                }
                if (outp.pos > 0) {
                    size_t w = fwrite(ob, 1, outp.pos, fout);
                    dst_sz += w;
                    if (w != outp.pos) { ret=1; break; }
                }
                if (inp.pos < inp.size) continue;
                if (last && r != 0) continue;
                break;
            } while (1);
            if (ret) break;
        }
        free(ib); free(ob);
        if (!is_stdin && !src_sz) { struct stat st; if(!stat(src,&st)) src_sz=st.st_size; }
        if (!is_stdout && !dst_sz) { struct stat st; fflush(fout); if(!fstat(fileno(fout),&st)) dst_sz=st.st_size; }
