    /* Show per-file result: always for single file, only with -v for multi-file */
    if (!is_stdout && g_verbosity >= VERB_NORMAL &&
        (g_num_total_files <= 1 || g_verbosity >= VERB_VERBOSE)) {
        char sb[32], db[32];
