static int decompress_file(const char *src, const char *dst, const Options *opts, ZSTD_DCtx *dctx) {
    int is_stdin = !strcmp(src, "-");
    int is_stdout = (!dst || !strcmp(dst, "-"));
    FILE *fin = NULL, *fout = NULL;
    int ret = 0;

    if (is_stdin) fin = stdin;
    else {
        fin = fopen(src, "rb");
        if (!fin) {
            fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n", src, strerror(errno));
            return 1;
        }
    }

    int fmt = detect_format(fin);
    if (fmt < 0) {
        if (opts->pass_through) {
            if (is_stdout) fout = stdout;
            else {
                if (!opts->force && file_exists(dst)) {
                    if (!ask_overwrite(dst)) { if(!is_stdin) fclose(fin); return 1; }
                }
                fout = fopen(dst, "wb");
                if (!fout) { fprintf(stderr,"zstd: can't create %s: %s\n",dst,strerror(errno)); if(!is_stdin)fclose(fin); return 1; }
            }
            unsigned char buf[65536]; size_t n;
            unsigned long long total = 0;
            while ((n = fread(buf,1,sizeof(buf),fin)) > 0) { fwrite(buf,1,n,fout); total+=n; }
            if (!is_stdin) fclose(fin);
            if (!is_stdout) fclose(fout);
            if (!is_stdout && g_verbosity>=VERB_NORMAL && (g_num_total_files<=1||g_verbosity>=VERB_VERBOSE))
