        if (!ib || !ob) { free(ib); free(ob); ret=1; goto dclean; }
        ZSTD_DCtx_reset(dctx, ZSTD_reset_session_only);
        size_t n;
        while ((n = fread(ib,1,in_sz,fin)) > 0) {
            ZSTD_inBuffer inp = {ib, n, 0};
            while (inp.pos < inp.size) {
                ZSTD_outBuffer outp = {ob, out_sz, 0};
