                    fprintf(stderr,"zstd: %s: decompression failed: %s\n",src,ZSTD_getErrorName(r));
                    ret=1; break;
                }
                if (outp.pos > 0) {
                    size_t w = fwrite(ob,1,outp.pos,fout);
                    dst_sz += w;
                    if (w != outp.pos) { ret=1; break; }
                }
            }
            if (ret) break;
        }
        free(ib); free(ob);
    }

dclean:
    if (!is_stdin) fclose(fin);
    if (!is_stdout) fclose(fout);
    if (ret) { if (!is_stdout && dst) unlink(dst); return ret; }

    /* Show per-file result */
    if (!is_stdout && g_verbosity>=VERB_NORMAL && (g_num_total_files<=1||g_verbosity>=VERB_VERBOSE))
        fprintf(stderr, "%-21s: %llu bytes \n", src, dst_sz);

    g_total_decomp_size += dst_sz;
    g_num_files_success++;
    return 0;
}

static int test_file(const char *path, ZSTD_DCtx *dctx) {
    FILE *fin = fopen(path, "rb");
    if (!fin) { fprintf(stderr,"zstd: can't open %s: %s\n",path,strerror(errno)); return 1; }
    int fmt = detect_format(fin);
    if (fmt < 0) { fprintf(stderr,"zstd: %s: unsupported format\n",path); fclose(fin); return 1; }
    size_t in_sz = ZSTD_DStreamInSize(), out_sz = ZSTD_DStreamOutSize();
