    while ((n = fread(ib,1,in_sz,fin)) > 0) {
        ZSTD_inBuffer inp = {ib, n, 0};
        while (inp.pos < inp.size) {
            ZSTD_outBuffer outp = {ob, out_sz, 0};
            size_t r = ZSTD_decompressStream(dctx, &outp, &inp);
            if (ZSTD_isError(r)) {
                fprintf(stderr,"zstd: %s: decompression failed: %s\n",path,ZSTD_getErrorName(r));
                ret=1; break;
