            total += outp.pos;
        }
        if (ret) break;
    }
    fclose(fin); free(ib); free(ob);
    if (!ret && g_verbosity>=VERB_NORMAL && (g_num_total_files<=1||g_verbosity>=VERB_VERBOSE))
        fprintf(stderr, "%-21s: %llu bytes \n", path, total);
