static void collect_recursive(const char *dir) {
    DIR *d = opendir(dir); if (!d) return;
    struct dirent *e;
    while ((e = readdir(d))) {
        if (!strcmp(e->d_name,".") || !strcmp(e->d_name,"..")) continue;
        char full[PATH_MAX]; snprintf(full, sizeof(full), "%s/%s", dir, e->d_name);
        struct stat st; if (stat(full, &st)) continue;
        if (S_ISDIR(st.st_mode)) collect_recursive(full);
        else if (S_ISREG(st.st_mode)) rec_add(full);
    }
    closedir(d);
}

static void *load_training_files(char **files, int n, size_t **sizes_out, unsigned *nsamp) {
    size_t total = 0;
    size_t *sizes = calloc(n, sizeof(size_t));
    if (!sizes) return NULL;
    for (int i = 0; i < n; i++) {
        struct stat st;
        if (!stat(files[i], &st)) { sizes[i]=st.st_size; total+=st.st_size; }
    }
    void *buf = malloc(total+1); if (!buf) { free(sizes); return NULL; }
    unsigned char *p = buf; *nsamp = 0;
    for (int i = 0; i < n; i++) {
        if (!sizes[i]) continue;
        FILE *f = fopen(files[i], "rb"); if (!f) { sizes[i]=0; continue; }
        size_t r = fread(p, 1, sizes[i], f); fclose(f);
        sizes[i]=r; p+=r; if (r>0) (*nsamp)++;
    }
    *sizes_out = sizes; return buf;
}

static int train_dictionary(Options *opts) {
    if (!opts->num_input_files) { fprintf(stderr,"zstd: no training files\n"); return 1; }
    const char *dict_name = opts->output_file ? opts->output_file : "dictionary";
    int maxdict = opts->maxdict ? opts->maxdict : DEFAULT_DICT_SIZE;
    size_t total = 0;
    for (int i=0; i<opts->num_input_files; i++) { struct stat st; if(!stat(opts->input_files[i],&st)) total+=st.st_size; }
    if (total < (size_t)maxdict*10) {
        fprintf(stderr,"!  Warning : data size of samples too small for target dictionary size \n");
        fprintf(stderr,"!  Samples should be about 100x larger than target dictionary size \n");
    }
    int si = opts->num_input_files > 16 ? 16 : 0;
    fprintf(stderr,"Loading %s...       \n\n", opts->input_files[si]);
    fprintf(stderr,"                                                                               \n");
    size_t *sizes = NULL; unsigned nsamp = 0;
    void *buf = load_training_files(opts->input_files, opts->num_input_files, &sizes, &nsamp);
    if (!buf) { fprintf(stderr,"zstd: failed to load training files\n"); return 1; }
    void *dict_buf = malloc(maxdict);
    if (!dict_buf) { free(buf); free(sizes); return 1; }
    size_t dict_size = 0;

    if (opts->train_mode == 3) {
        ZDICT_legacy_params_t params; memset(&params,0,sizeof(params));
        params.selectivityLevel = opts->tlegacy_s ? opts->tlegacy_s : 9;
        params.notificationLevel = 2;
        fprintf(stderr,"\n                                                                      \n");
        fprintf(stderr,"sorting %d files of total size %d MB ...\n", nsamp, (int)(total/1048576));
        fprintf(stderr,"finding patterns ... \n");
        dict_size = ZDICT_trainFromBuffer_legacy(dict_buf, maxdict, buf, sizes, nsamp, params);
    } else if (opts->train_mode == 2) {
        ZDICT_cover_params_t params; memset(&params,0,sizeof(params));
        params.k=opts->tk; params.d=opts->td;
        params.steps=opts->tsteps?opts->tsteps:40;
        params.splitPoint=opts->tsplitd>0?opts->tsplitd:1.0;
        params.notificationLevel=2;
        if (opts->dictID) params.dictID=opts->dictID;
        dict_size = ZDICT_optimizeTrainFromBuffer_cover(dict_buf, maxdict, buf, sizes, nsamp, &params);
    } else {
        ZDICT_fastCover_params_t params; memset(&params,0,sizeof(params));
        params.k=opts->tk; params.d=opts->td;
        params.f=opts->tf?opts->tf:20;
        params.steps=opts->tsteps?opts->tsteps:(opts->train_mode==1?40:5);
        params.accel=opts->taccel?opts->taccel:1;
        params.splitPoint=opts->tsplitd>0?opts->tsplitd:0.75;
        params.notificationLevel=2;
        if (opts->dictID) params.dictID=opts->dictID;
        dict_size = ZDICT_optimizeTrainFromBuffer_fastCover(dict_buf, maxdict, buf, sizes, nsamp, &params);
    }

    if (ZDICT_isError(dict_size)) {
        fprintf(stderr,"zstd: dictionary training failed : %s\n", ZDICT_getErrorName(dict_size));
        free(buf); free(sizes); free(dict_buf); return 1;
    }
    FILE *f = fopen(dict_name, "wb");
    if (!f) { fprintf(stderr,"zstd: can't create dictionary %s: %s\n",dict_name,strerror(errno)); free(buf);free(sizes);free(dict_buf); return 1; }
    fwrite(dict_buf, 1, dict_size, f); fclose(f);
    fprintf(stderr,"Save dictionary of size %zu into file %s \n", dict_size, dict_name);
    free(buf); free(sizes); free(dict_buf); return 0;
}

static void parse_train_params(const char *params, Options *opts) {
    if (!params||!*params) return;
    char *p = strdup(params), *t = strtok(p, ",");
    while (t) {
        if (!strncmp(t,"k=",2)) opts->tk=atoi(t+2);
        else if (!strncmp(t,"d=",2)) opts->td=atoi(t+2);
        else if (!strncmp(t,"f=",2)) opts->tf=atoi(t+2);
        else if (!strncmp(t,"steps=",6)) opts->tsteps=atoi(t+6);
        else if (!strncmp(t,"split=",6)) { opts->tsplit=atoi(t+6); opts->tsplitd=opts->tsplit/100.0; }
        else if (!strncmp(t,"accel=",6)) opts->taccel=atoi(t+6);
        else if (!strncmp(t,"s=",2)) opts->tlegacy_s=atoi(t+2);
        else if (!strncmp(t,"shrink=",7)) opts->tshrink=atoi(t+7);
        else if (!strcmp(t,"shrink")) opts->tshrink=1;
        t = strtok(NULL, ",");
    }
    free(p);
}

static ZSTD_CCtx *create_cctx(const Options *opts) {
    ZSTD_CCtx *c = ZSTD_createCCtx(); if (!c) return NULL;
    int level = opts->fast > 0 ? -opts->fast : opts->compress_level;
    ZSTD_CCtx_setParameter(c, ZSTD_c_compressionLevel, level);
    ZSTD_CCtx_setParameter(c, ZSTD_c_checksumFlag, opts->no_check ? 0 : 1);
    ZSTD_CCtx_setParameter(c, ZSTD_c_contentSizeFlag, 1);
    if (opts->no_dictID) ZSTD_CCtx_setParameter(c, ZSTD_c_dictIDFlag, 0);
    if (opts->long_distance) {
        ZSTD_CCtx_setParameter(c, ZSTD_c_enableLongDistanceMatching, 1);
        if (opts->long_window_log > 0) ZSTD_CCtx_setParameter(c, ZSTD_c_ldmHashLog, opts->long_window_log);
    }
    if (opts->nb_workers > 0) ZSTD_CCtx_setParameter(c, ZSTD_c_nbWorkers, opts->nb_workers);
    return c;
}

static char *get_comp_dst(const char *src, const Options *opts) {
    if (opts->output_file) return strdup(opts->output_file);
    if (opts->stdout_mode) return strdup("-");
    const char *suf = (opts->format==FMT_GZIP) ? ".gz" : ".zst";
    if (opts->output_dir_flat) {
        const char *b = strrchr(src,'/'); if(b) b++; else b=src;
        char *r = malloc(strlen(opts->output_dir_flat)+strlen(b)+strlen(suf)+5);
        sprintf(r,"%s/%s%s",opts->output_dir_flat,b,suf);
        mkdirp(opts->output_dir_flat, 0755); return r;
    }
    if (opts->output_dir_mirror) {
        const char *rel = src; if(rel[0]=='/') rel++;
        char *r = malloc(strlen(opts->output_dir_mirror)+strlen(rel)+strlen(suf)+5);
        sprintf(r,"%s/%s%s",opts->output_dir_mirror,rel,suf);
        create_parent_dirs(r); return r;
    }
    char *r = malloc(strlen(src)+strlen(suf)+5);
    sprintf(r,"%s%s",src,suf); return r;
}

static char *get_decomp_dst(const char *src, const Options *opts) {
    if (opts->output_file) return strdup(opts->output_file);
    if (opts->stdout_mode) return strdup("-");
    int known; char *base = get_decomp_output(src, &known);
    if (!known) {
        if (!opts->force) {
            fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",src);
            free(base); return NULL;
        }
        free(base); base = strdup(src);
    }
    if (opts->output_dir_flat) {
        const char *b = strrchr(base,'/'); if(b) b++; else b=base;
        char *r = malloc(strlen(opts->output_dir_flat)+strlen(b)+5);
        sprintf(r,"%s/%s",opts->output_dir_flat,b);
        mkdirp(opts->output_dir_flat,0755); free(base); return r;
    }
    if (opts->output_dir_mirror) {
        const char *rel = base; if(rel[0]=='/') rel++;
        char *r = malloc(strlen(opts->output_dir_mirror)+strlen(rel)+5);
        sprintf(r,"%s/%s",opts->output_dir_mirror,rel);
        create_parent_dirs(r); free(base); return r;
    }
    return base;
}

static int process_file(const char *src, const Options *opts, ZSTD_CCtx *cctx, ZSTD_DCtx *dctx) {
    if (opts->test_mode) return test_file(src, dctx);
    if (opts->decompress) {
        char *dst = get_decomp_dst(src, opts);
        if (!dst && !opts->force) return 1;
        if (!dst) dst = strdup("-");
        int r = decompress_file(src, dst, opts, dctx);
        free(dst);
        if (!r && !opts->keep && strcmp(src,"-")) unlink(src);
        return r;
    } else {
        if (opts->exclude_compressed) {
            FILE *f = fopen(src,"rb");
            if (f) { int fmt=detect_format(f); fclose(f);
                if (fmt>=0) { if(g_verbosity>=VERB_VERBOSE) fprintf(stderr,"zstd: %s already compressed, skipping\n",src); return 0; } }
        }
        char *dst = get_comp_dst(src, opts);
        int r = compress_file(src, dst, opts, cctx);
        free(dst);
        if (!r && !opts->keep && strcmp(src,"-")) unlink(src);
        return r;
    }
}

