typedef struct {
    unsigned long long compressed, uncompressed;
    int frames, skips, check_type;
} FileInfo;

static int get_file_info(const char *path, FileInfo *info) {
    memset(info, 0, sizeof(*info));
    FILE *f = fopen(path, "rb"); if (!f) return -1;
    fseek(f, 0, SEEK_END); long fsz = ftell(f); fseek(f, 0, SEEK_SET);
    if (fsz < 0) { fclose(f); return -1; }
    info->compressed = fsz;
    unsigned char *data = malloc(fsz); if (!data) { fclose(f); return -1; }
    if (fread(data, 1, fsz, f) != (size_t)fsz) { fclose(f); free(data); return -1; }
    fclose(f);
    unsigned char *p = data; size_t rem = fsz;
    while (rem >= 4) {
        unsigned magic = p[0]|(p[1]<<8)|(p[2]<<16)|(p[3]<<24);
        if ((magic & 0xFFFFFFF0U) == 0x184D2A50U) {
            if (rem < 8) break;
            unsigned ss = p[4]|(p[5]<<8)|(p[6]<<16)|(p[7]<<24);
            info->skips++;
            size_t ts = 8 + ss; if (ts > rem) break;
            p += ts; rem -= ts; continue;
        }
        if (magic != 0xFD2FB528U) break;
        ZSTD_frameHeader fh;
        size_t hr = ZSTD_getFrameHeader(&fh, p, rem);
        if (ZSTD_isError(hr) || hr > 0) break;
        size_t fs = ZSTD_findFrameCompressedSize(p, rem);
        if (ZSTD_isError(fs)) break;
        info->frames++;
        if (fh.checksumFlag) info->check_type = 1;
        if (fh.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN && fh.frameContentSize != ZSTD_CONTENTSIZE_ERROR) {
            info->uncompressed += fh.frameContentSize;
        } else {
            ZSTD_DCtx *dc = ZSTD_createDCtx();
            size_t osz = ZSTD_DStreamOutSize(); void *ob = malloc(osz);
            unsigned long long tot = 0;
            if (ob) {
                ZSTD_inBuffer inp = {p, fs, 0};
                ZSTD_DCtx_reset(dc, ZSTD_reset_session_only);
                while (inp.pos < inp.size) {
                    ZSTD_outBuffer outp = {ob, osz, 0};
                    if (ZSTD_isError(ZSTD_decompressStream(dc, &outp, &inp))) break;
                    tot += outp.pos;
                }
                free(ob);
            }
            ZSTD_freeDCtx(dc);
            info->uncompressed += tot;
        }
        p += fs; if (fs > rem) break; rem -= fs;
    }
    free(data); return 0;
}

static void print_list_header(void) {
    printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
}

static void print_list_entry(const FileInfo *info, const char *filename) {
