            printf("Ratio: %.4f\n", ratio);
            /* Check */
            if (fh.checksumFlag) {
                /* Compute XXH64 of decompressed data */
                ZSTD_DCtx *dc = ZSTD_createDCtx();
                ZSTD_DCtx_loadDictionary(dc, NULL, 0); /* reset */
                size_t fs2 = ZSTD_findFrameCompressedSize(p, rem);
                unsigned long long chk = 0;
                if (!ZSTD_isError(fs2)) {
                    void *decomp = malloc(ds + 1);
                    if (decomp) {
                        size_t r = ZSTD_decompress(decomp, ds+1, p, fs2);
                        if (!ZSTD_isError(r)) {
                            chk = ZSTD_XXH64(decomp, r, 0);
                        }
                        free(decomp);
                    }
                }
                ZSTD_freeDCtx(dc);
                printf("Check: XXH64 %08llx\n", chk & 0xFFFFFFFF);
            } else {
                printf("Check: None\n");
            }
        }
    }
    printf("\n");
    free(data);
}

