    if (!opts.list_mode && g_verbosity >= VERB_NORMAL) {
        if (!opts.decompress && !opts.test_mode && g_num_files_success > 1) {
            char sb[32], db[32];
            fmt_size_6(g_total_src_size, sb, sizeof(sb));
