            if(cctx) ZSTD_freeCCtx(cctx); if(dctx) ZSTD_freeDCtx(dctx); return 1;
        }
        if (cctx) ZSTD_CCtx_loadDictionary(cctx, dict_data, dict_size);
        if (dctx) ZSTD_DCtx_loadDictionary(dctx, dict_data, dict_size);
    }

    if (opts.list_mode) print_list_header();

    int global_ret = 0;
    FileInfo list_total; memset(&list_total, 0, sizeof(list_total));
    int list_count = 0;

    for (int j = 0; j < final_count; j++) {
        const char *src = final_files[j];
        if (opts.list_mode) {
            FileInfo info;
            if (!get_file_info(src, &info)) {
                if (g_verbosity >= VERB_VERBOSE) {
                    print_list_entry_verbose(&info, src, src);
                } else {
                    print_list_entry(&info, src);
                    list_total.compressed += info.compressed;
                    list_total.uncompressed += info.uncompressed;
                    list_total.frames += info.frames;
                    list_total.skips += info.skips;
                    if (info.check_type) list_total.check_type = info.check_type;
                    list_count++;
                }
            } else {
                global_ret = 1;
            }
            continue;
        }
        int ret = process_file(src, &opts, cctx, dctx);
        if (ret) global_ret = 1;
    }

    if (opts.list_mode && list_count > 1 && g_verbosity < VERB_VERBOSE)
        print_list_summary(list_count, &list_total);

    /* Summary output */
    if (!opts.list_mode && g_verbosity >= VERB_NORMAL) {
        if (!opts.decompress && !opts.test_mode && g_num_files_success > 1) {
            char sb[32], db[32];
            fmt_size_6(g_total_src_size, sb, sizeof(sb));
            fmt_size_6(g_total_dst_size, db, sizeof(db));
            double ratio = g_total_src_size ? g_total_dst_size*100.0/g_total_src_size : 0.0;
            fprintf(stderr,"  %d files compressed : %6.2f%% (%s => %s)\n",
                    g_num_files_success, ratio, sb, db);
        } else if (opts.decompress && !opts.test_mode && g_num_files_success > 1) {
            fprintf(stderr,"%d files decompressed : %6llu bytes total \n",
                    g_num_files_success, g_total_decomp_size);
        }
    }

    if (cctx) ZSTD_freeCCtx(cctx);
    if (dctx) ZSTD_freeDCtx(dctx);
    free(dict_data);
    return global_ret;
